<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>WastedToken Mint — Collectible Challenge Coins</title>
<style>
:root{
  --bg:#0a0a10; --panel:#14141e; --line:rgba(230,196,106,.18);
  --gold:#e6c46a; --gold2:#f4dfa0; --ink:#ece7d8; --mut:#9b94a6;
  --mono:'Courier New',ui-monospace,Menlo,monospace;
  --serif:Georgia,'Times New Roman',Times,serif;
  --sans:'Helvetica Neue',Arial,system-ui,sans-serif;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  background:radial-gradient(1200px 700px at 72% -10%,#181824 0%,var(--bg) 55%);
  color:var(--ink);font-family:var(--sans);line-height:1.65;
  -webkit-font-smoothing:antialiased;overflow-x:hidden;
}
::selection{background:var(--gold);color:#171104}
a{color:inherit;text-decoration:none}
.wrap{max-width:1180px;margin:0 auto;padding:0 24px}

/* ---------- nav ---------- */
nav{position:fixed;inset:0 0 auto 0;z-index:50;backdrop-filter:blur(12px);
  background:rgba(10,10,16,.72);border-bottom:1px solid var(--line)}
nav .wrap{display:flex;align-items:center;gap:14px;height:64px}
.brand{display:flex;align-items:center;gap:11px;font:700 15px var(--serif);letter-spacing:.14em}
.brand small{display:block;font:700 8.5px var(--mono);letter-spacing:.42em;color:var(--gold)}
.mark{width:30px;height:30px;flex:none}
nav .links{margin-left:auto;display:flex;gap:26px;font:700 10.5px var(--mono);letter-spacing:.24em}
nav .links a{color:var(--mut);transition:color .25s}
nav .links a:hover{color:var(--gold2)}
.cart{background:transparent;border:1px solid var(--line);color:var(--gold2);
  font:700 10.5px var(--mono);letter-spacing:.2em;padding:9px 14px;cursor:pointer;transition:.25s}
.cart:hover{border-color:var(--gold);background:rgba(230,196,106,.08)}
@media(max-width:760px){nav .links{display:none}}

/* ---------- hero ---------- */
.hero{min-height:100vh;display:grid;grid-template-columns:1.05fr .95fr;align-items:center;
  gap:48px;padding-top:120px;padding-bottom:70px}
@media(max-width:920px){.hero{grid-template-columns:1fr;padding-top:110px}}
.kicker{font:700 10.5px var(--mono);letter-spacing:.4em;color:var(--gold);text-transform:uppercase}
.kicker::before{content:"";display:inline-block;width:34px;height:1px;background:var(--gold);
  vertical-align:middle;margin-right:12px;opacity:.7}
h1{font:400 clamp(42px,5.4vw,74px)/1.04 var(--serif);margin:22px 0 20px;letter-spacing:-.01em}
h1 em{font-style:italic;background:linear-gradient(100deg,var(--gold2),var(--gold) 55%,#a97e2c);
  -webkit-background-clip:text;background-clip:text;color:transparent}
.lede{max-width:52ch;color:var(--mut);font-size:16.5px}
.cta{display:flex;gap:14px;margin:32px 0 36px;flex-wrap:wrap}
.btn{font:700 11px var(--mono);letter-spacing:.24em;padding:15px 24px;border:1px solid var(--gold);
  transition:.25s;cursor:pointer;display:inline-block}
.btn.primary{background:linear-gradient(180deg,var(--gold2),var(--gold));color:#241a05}
.btn.primary:hover{filter:brightness(1.12);transform:translateY(-2px)}
.btn.ghost{color:var(--gold2)}
.btn.ghost:hover{background:rgba(230,196,106,.08)}
.hero-stats{display:flex;gap:34px;list-style:none;flex-wrap:wrap}
.hero-stats b{display:block;font:400 26px var(--serif);color:var(--gold2)}
.hero-stats span{font:700 9.5px var(--mono);letter-spacing:.28em;color:var(--mut)}

.stage{position:relative;max-width:560px;width:100%;margin:0 auto;
  border:1px solid var(--line);background:#0d0d15;padding:18px}
.stage::before,.stage::after{content:"";position:absolute;width:22px;height:22px;pointer-events:none}
.stage::before{top:-1px;left:-1px;border-top:2px solid var(--gold);border-left:2px solid var(--gold)}
.stage::after{bottom:-1px;right:-1px;border-bottom:2px solid var(--gold);border-right:2px solid var(--gold)}
.stage canvas{width:100%;height:auto;display:block}
.stage figcaption{display:flex;align-items:center;gap:9px;margin-top:14px;
  font:700 9.5px var(--mono);letter-spacing:.3em;color:var(--mut)}
.dot{width:7px;height:7px;border-radius:50%;background:#e05252;flex:none;
  box-shadow:0 0 10px #e05252;animation:pulse 1.6s infinite}
@keyframes pulse{50%{opacity:.35}}

/* ---------- ticker ---------- */
.ticker{border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  background:#0d0d14;overflow:hidden;padding:13px 0}
.ticker-inner{display:flex;width:max-content;animation:mar 32s linear infinite}
.ticker-inner span{font:700 10.5px var(--mono);letter-spacing:.32em;color:var(--gold);
  white-space:nowrap;padding-right:18px}
@keyframes mar{to{transform:translateX(-50%)}}

/* ---------- sections ---------- */
section{padding:110px 0}
h2{font:400 clamp(30px,3.6vw,46px)/1.12 var(--serif);margin:18px 0 14px}
.sub{color:var(--mut);max-width:60ch}

