  gold:   {base:'#caa14e',light:'rgba(255,240,190,0.55)',dark:'rgba(70,45,10,0.55)',dev:'#f3dd9a',devSoft:'#dcbf72',deep:'#6e5115',field2:'#d9b661',edge:[150,112,46],spec:[255,244,214],rim:[255,224,148],specStr:1.55,rimStr:0.32,sheen:0.14},
