  bronze: {base:'#a5713a',light:'rgba(255,214,160,0.50)',dark:'rgba(50,28,8,0.60)',dev:'#e9b878',devSoft:'#c99a5c',deep:'#5e3c16',field2:'#b07e44',edge:[112,72,31],spec:[255,230,198],rim:[255,204,148],specStr:1.4,rimStr:0.28,sheen:0.13},
  obsidian:{base:'#191922',light:'rgba(120,128,170,0.35)',dark:'rgba(0,0,0,0.70)',dev:'#3c3f55',devSoft:'#2b2d3d',deep:'#959cc9',field2:'#20202c',edge:[34,34,46],spec:[236,241,255],rim:[150,160,255],specStr:2.3,rimStr:0.5,sheen:0.2}
};

/* ---------- coin face drawing helpers ---------- */
function ring(x,cx,cy,rad,w,style){x.beginPath();x.arc(cx,cy,rad,0,6.2832);x.lineWidth=w;x.strokeStyle=style;x.stroke();}

function arcText(x,text,cx,cy,rad,ca,spread,font,fill,dir){
  x.font=font;x.textAlign='center';x.textBaseline='middle';x.fillStyle=fill;
  var n=text.length;
  for(var i=0;i<n;i++){
    var f=n===1?0.5:i/(n-1);
    var a=dir===1?ca-spread+2*spread*f:ca+spread-2*spread*f;
    x.save();x.translate(cx+Math.cos(a)*rad,cy+Math.sin(a)*rad);
    x.rotate(a+(dir===1?Math.PI/2:-Math.PI/2));
    x.fillText(text[i],0,0);x.restore();
  }
}
function spacedText(x,text,px,py,sp){
  var n=text.length,x0=px-(n-1)/2*sp;
  for(var i=0;i<n;i++)x.fillText(text[i],x0+i*sp,py);
}
function star4(x,px,py,r,fill){
  x.beginPath();
  for(var i=0;i<8;i++){
    var a=i/8*6.2832-Math.PI/2,rr=i%2===0?r:r*0.3;
    var qx=px+Math.cos(a)*rr,qy=py+Math.sin(a)*rr;
    i===0?x.moveTo(qx,qy):x.lineTo(qx,qy);
  }
  x.closePath();x.fillStyle=fill;x.fill();
}
function crown(x,px,py,w,h,fill,stroke){
  x.beginPath();
  x.moveTo(px-w/2,py+h/2);x.lineTo(px-w/2,py-h*0.15);x.lineTo(px-w*0.22,py+h*0.02);
  x.lineTo(px,py-h*0.5);x.lineTo(px+w*0.22,py+h*0.02);x.lineTo(px+w/2,py-h*0.15);
  x.lineTo(px+w/2,py+h/2);x.closePath();x.fillStyle=fill;x.fill();
  if(stroke){x.lineWidth=1.5;x.strokeStyle=stroke;x.globalAlpha=.5;x.stroke();x.globalAlpha=1;}
}

/* Draws the full raised design. mode 'c' = albedo, mode 'h' = heightmap */
function drawDesign(x,S,kind,denom,pal,mode){
  var R=S/2,cx=R,cy=R,H=mode==='h';
  var colMain=H?'#ffffff':pal.dev;
  var colSoft=H?'rgba(255,255,255,0.72)':pal.devSoft;
  /* rims + beaded border */
  ring(x,cx,cy,R*0.94,S*0.020,colMain);
  ring(x,cx,cy,R*0.885,S*0.006,colSoft);
  x.fillStyle=colSoft;
  for(var i=0;i<64;i++){
    var a=i/64*6.2832;
    x.beginPath();x.arc(cx+Math.cos(a)*R*0.915,cy+Math.sin(a)*R*0.915,S*0.0045,0,6.2832);x.fill();
  }
  /* legend around the rim */
  var fArc='700 '+(S*0.052)+'px Georgia,"Times New Roman",serif';
  arcText(x,'WASTEDTOKEN MINT',cx,cy,R*0.745,-Math.PI/2,1.02,fArc,colMain,1);
  arcText(x,kind==='emblem'?'· PROOF OF WASTE ·':'· NOT LEGAL TENDER ·',
          cx,cy,R*0.745,Math.PI/2,0.98,fArc,colMain,-1);

  if(kind==='emblem'){
    /* starburst */
    x.beginPath();
    for(var k=0;k<28;k++){
      var sa=k/28*6.2832-Math.PI/2,rr=k%2===0?R*0.36:R*0.285;
      var qx=cx+Math.cos(sa)*rr,qy=cy+Math.sin(sa)*rr;
      k===0?x.moveTo(qx,qy):x.lineTo(qx,qy);
    }
    x.closePath();x.fillStyle=colSoft;x.fill();
    if(!H){x.lineWidth=S*0.004;x.strokeStyle=pal.deep;x.globalAlpha=.5;x.stroke();x.globalAlpha=1;}
    /* central disk + monogram */
    x.beginPath();x.arc(cx,cy,R*0.245,0,6.2832);x.fillStyle=H?'#e6e6e6':pal.field2;x.fill();
    ring(x,cx,cy,R*0.245,S*0.008,H?'#fff':pal.dev);
    ring(x,cx,cy,R*0.205,S*0.003,colSoft);
    x.fillStyle=H?'#ffffff':pal.deep;
    x.font='900 '+(S*0.21)+'px Georgia,"Times New Roman",serif';
    x.textAlign='center';x.textBaseline='middle';
    x.fillText('W',cx,cy+S*0.008);
    crown(x,cx,cy-R*0.40,R*0.20,R*0.13,H?'#fff':pal.dev,H?null:pal.deep);
    x.font='700 '+(S*0.030)+'px Georgia,"Times New Roman",serif';
    x.fillStyle=H?'rgba(255,255,255,0.8)':pal.devSoft;
    spacedText(x,'EST · MMXXIV',cx,cy+R*0.44,S*0.036);
    star4(x,cx-R*0.55,cy,S*0.018,colSoft);
    star4(x,cx+R*0.55,cy,S*0.018,colSoft);
  }else{
    /* denomination: big token count */
    var fs=denom.length>5?S*0.165:S*0.19;
    x.font='900 '+fs+'px Georgia,"Times New Roman",serif';
    x.textAlign='center';x.textBaseline='middle';
    if(!H){x.save();x.globalAlpha=.35;x.fillStyle=pal.deep;
      x.fillText(denom,cx+S*0.004,cy-S*0.01+S*0.006);x.restore();}
    x.fillStyle=H?'#fff':pal.dev;
    x.fillText(denom,cx,cy-S*0.01);
    crown(x,cx,cy-R*0.33,R*0.16,R*0.10,H?'rgba(255,255,255,0.85)':pal.devSoft,H?null:pal.deep);
    x.strokeStyle=colSoft;x.lineWidth=S*0.005;
    x.beginPath();x.moveTo(cx-R*0.27,cy+S*0.10);x.lineTo(cx+R*0.27,cy+S*0.10);x.stroke();
    x.font='700 '+(S*0.072)+'px Georgia,"Times New Roman",serif';
    x.fillStyle=colMain;
    spacedText(x,'TOKENS',cx,cy+S*0.185,S*0.088);
    star4(x,cx-R*0.55,cy+S*0.185,S*0.016,colSoft);
    star4(x,cx+R*0.55,cy+S*0.185,S*0.016,colSoft);
  }
}

/* Build one coin face: returns {c: RGBA albedo, h: RGBA height, size} */
function buildFace(kind,denom,pal,seed){
  var S=512,R=S/2,rng=mulberry32(seed);
  var cv=document.createElement('canvas');cv.width=cv.height=S;
  var c=cv.getContext('2d');
  var hc=document.createElement('canvas');hc.width=hc.height=S;
  var h=hc.getContext('2d');
  /* brushed metal field */
  c.fillStyle=pal.base;c.fillRect(0,0,S,S);
  var g=c.createRadialGradient(R,R,S*0.06,R,R,R*1.02);
  g.addColorStop(0,pal.light);g.addColorStop(.55,'rgba(0,0,0,0)');g.addColorStop(1,pal.dark);
  c.fillStyle=g;c.fillRect(0,0,S,S);
  c.save();c.beginPath();c.arc(R,R,R*0.99,0,6.2832);c.clip();
  for(var i=0;i<340;i++){
    c.beginPath();c.arc(R,R,rng()*R,0,6.2832);
    c.strokeStyle=rng()>.5?'rgba(255,255,255,'+(0.012+rng()*0.03)+')':'rgba(0,0,0,'+(0.012+rng()*0.03)+')';
    c.lineWidth=.5+rng()*1.5;c.stroke();
  }
  c.restore();
  h.fillStyle='#000';h.fillRect(0,0,S,S);
  drawDesign(c,S,kind,denom,pal,'c');
  drawDesign(h,S,kind,denom,pal,'h');
  if('filter' in h){h.filter='blur(2px)';h.drawImage(hc,0,0);h.filter='none';}
  var cd=c.getImageData(0,0,S,S),hd=h.getImageData(0,0,S,S);
  for(var j=0;j<cd.data.length;j+=4){var n=(rng()*7-3.5)|0;
    cd.data[j]+=n;cd.data[j+1]+=n;cd.data[j+2]+=n;}
  return{c:cd.data,h:hd.data,size:S};
}

/* ============================================================
   Software 3D coin renderer.
   A capped cylinder ray-cast per pixel into an ImageData.
   Pure function of (angleY, angleX, light) → pixels.
   ============================================================ */
function createCoinStage(canvas,cfg){
  var S=cfg.size,ctx=canvas.getContext('2d');
  canvas.width=S;canvas.height=S;
  var img=ctx.createImageData(S,S),data=img.data;
  var cov=new Uint8Array(S*S);
  /* simple static backdrop (subtle radial, faint grain) */
  var bd=new Uint8ClampedArray(S*S*4);
  (function(){
    var rng=mulberry32(cfg.seed||7),cc=(S-1)/2;
    for(var y=0;y<S;y++)for(var x=0;x<S;x++){
      var dx=(x-cc)/cc,dy=(y-cc)/cc;
      var f=Math.max(0,1-0.5*(dx*dx+dy*dy)),i=(y*S+x)*4,n=rng()*4-2;
      bd[i]=cfg.bg0[0]*f+cfg.bg1[0]*(1-f)+n;
      bd[i+1]=cfg.bg0[1]*f+cfg.bg1[1]*(1-f)+n;
      bd[i+2]=cfg.bg0[2]*f+cfg.bg1[2]*(1-f)+n;
      bd[i+3]=255;
    }
  })();

  function render(ay,ax,L){
    var pal=cfg.pal,front=cfg.front,back=cfg.back;
    var R=cfg.R,hh=cfg.h,R2=R*R,hE=hh+1e-4,R2e=R2+1e-4;
    var ca=Math.cos(ay),sa=Math.sin(ay),cb=Math.cos(ax),sb=Math.sin(ax);
    /* M = Ry(ay)·Rx(ax) : coin-local → world */
    var M00=ca,M01=sa*sb,M02=sa*cb,M11=cb,M12=-sb,M20=-sa,M21=ca*sb,M22=ca*cb;
    var dx=sa,dy=-ca*sb,dz=-ca*cb;      /* ray dir in coin-local space */
    var a2=dx*dx+dy*dy;
    var Hc=S/2,du=1/Hc,Z0=60;
    var Lx=L.x,Ly=L.y,Lz=L.z;
    var Hx=Lx,Hy=Ly,Hz=Lz+1,iH=1/Math.sqrt(Hx*Hx+Hy*Hy+Hz*Hz);
    Hx*=iH;Hy*=iH;Hz*=iH;
    /* conservative projected bounds of the cylinder */
    var ex=R*Math.sqrt(M00*M00+M01*M01)+hh*Math.abs(M02);
    var ey=R*Math.abs(M11)+hh*Math.abs(M12);
    var px0=Math.max(0,Math.floor(Hc-0.5-ex*Hc)-1),px1=Math.min(S-1,Math.ceil(Hc-0.5+ex*Hc)+1);
    var py0=Math.max(0,Math.floor(Hc-0.5-ey*Hc)-1),py1=Math.min(S-1,Math.ceil(Hc-0.5+ey*Hc)+1);

    data.set(bd);cov.fill(0);
    var TW=front.size,TWM=TW-1,KH=cfg.KH||0.0042;
    var amb=0.30,dS=1.0,dS2=0.20;
    var eR=pal.edge[0],eG=pal.edge[1],eB=pal.edge[2];
    var spR=pal.spec[0],spG=pal.spec[1],spB=pal.spec[2];
    var rmR=pal.rim[0],rmG=pal.rim[1],rmB=pal.rim[2];
    var specStr=pal.specStr,rimStr=pal.rimStr,sheenStr=pal.sheen;
    var REEDS=cfg.reeds||110;

    for(var py=py0;py<=py1;py++){
      var wy=(Hc-py-0.5)*du,wx0=(px0+0.5-Hc)*du;
      var ox=ca*wx0-sa*Z0,
          oy=sa*sb*wx0+cb*wy+ca*sb*Z0,
          oz=sa*cb*wx0-sb*wy+ca*cb*Z0;
      var dox=ca*du,doy=sa*sb*du,doz=sa*cb*du;
      var idx=py*S+px0;
      for(var px=px0;px<=px1;px++,idx++,ox+=dox,oy+=doy,oz+=doz){
        var type=0,t=0;
        var bb=ox*dx+oy*dy,cc=ox*ox+oy*oy-R2;
        if(a2>1e-8){                       /* side of the cylinder */
          var disc=bb*bb-a2*cc;
          if(disc>0){
            var tt=(-bb-Math.sqrt(disc))/a2;
            if(tt>1e-4){var pz=oz+tt*dz;if(pz<=hE&&pz>=-hE){type=1;t=tt;}}
          }
        }
        if(dz>1e-8||dz<-1e-8){             /* front / back caps */
          var t2=(hh-oz)/dz;
          if(t2>1e-4&&(type===0||t2<t)){
            var qx=ox+t2*dx,qy=oy+t2*dy;
            if(qx*qx+qy*qy<=R2e){type=2;t=t2;}
          }
          t2=(-hh-oz)/dz;
          if(t2>1e-4&&(type===0||t2<t)){
            qx=ox+t2*dx;qy=oy+t2*dy;
            if(qx*qx+qy*qy<=R2e){type=3;t=t2;}
          }
        }
        if(type===0)continue;

        var lx=ox+t*dx,ly=oy+t*dy,nx,ny,nz,br,bgc,bl,boost=1;
        if(type===1){                      /* reeded edge */
          nx=lx/R;ny=ly/R;nz=0;
          var reed=Math.sin(Math.atan2(ly,lx)*REEDS);
          var rm=0.66+0.34*reed*reed;
          br=eR*rm;bgc=eG*rm;bl=eB*rm;
        }else{                             /* a face: albedo + relief normal */
          var tex=type===2?front:back;
          var tx=((lx/R*0.5+0.5)*TWM)|0;if(tx<0)tx=0;else if(tx>TWM)tx=TWM;
          var ty=((0.5-ly/R*0.5)*TWM)|0;if(ty<0)ty=0;else if(ty>TWM)ty=TWM;
          var cd=tex.c,hd=tex.h,ti=(ty*TW+tx)*4;
          br=cd[ti];bgc=cd[ti+1];bl=cd[ti+2];
          var xl=tx>1?tx-2:0,xr=tx<TWM-1?tx+2:TWM;
          var yu=ty>1?ty-2:0,yd=ty<TWM-1?ty+2:TWM;
          nx=-(hd[(ty*TW+xr)*4]-hd[(ty*TW+xl)*4])*KH;
          ny=-(hd[(yu*TW+tx)*4]-hd[(yd*TW+tx)*4])*KH;
          nz=type===2?1:-1;
          var il=1/Math.sqrt(nx*nx+ny*ny+1);nx*=il;ny*=il;nz*=il;
          boost=0.72+0.55*(hd[ti]/255);
        }
        /* to world space */
        var nxw=M00*nx+M01*ny+M02*nz,
            nyw=M11*ny+M12*nz,
            nzw=M20*nx+M21*ny+M22*nz;
        var dif=nxw*Lx+nyw*Ly+nzw*Lz;if(dif<0)dif=0;
        var dif2=nxw*L2.x+nyw*L2.y+nzw*L2.z;if(dif2<0)dif2=0;
        var sp=nxw*Hx+nyw*Hy+nzw*Hz;if(sp<0)sp=0;
        var s2=sp*sp,s4=s2*s2,s8=s4*s4,s16=s8*s8,s32=s16*s16;
        var spec,sheen=s4*s2*sheenStr;      /* broad moving sheen */
        if(type===1)spec=s8*s4*1.2*specStr; /* wide glint on the edge */
        else spec=s32*s16*specStr*boost;    /* tight rake on the faces */
        var shade=amb+dif*dS+dif2*dS2;
        var fr=1-(nzw<0?-nzw:nzw),rim=fr*fr*fr*rimStr;
        var o=idx*4;
        data[o]  =br*shade +(spR*0.55+br*0.45)*(spec+sheen)+rmR*rim;
        data[o+1]=bgc*shade+(spG*0.55+bgc*0.45)*(spec+sheen)+rmG*rim;
        data[o+2]=bl*shade +(spB*0.55+bl*0.45)*(spec+sheen)+rmB*rim;
        cov[idx]=1;
      }
    }
    /* silhouette anti-alias: blend only boundary pixels */
    for(var ay2=1;ay2<S-1;ay2++){
      var ii=ay2*S+1;
      for(var ax2=1;ax2<S-1;ax2++,ii++){
        var cnt=cov[ii-1]+cov[ii+1]+cov[ii-S]+cov[ii+S]+
                cov[ii-S-1]+cov[ii-S+1]+cov[ii+S-1]+cov[ii+S+1]+cov[ii];
        if(cnt===0||cnt===9)continue;
        var sr=0,sg=0,sb3=0,q;
        if(cov[ii-S-1]){q=(ii-S-1)*4;sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii-S]  ){q=(ii-S)*4;  sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii-S+1]){q=(ii-S+1)*4;sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii-1]  ){q=(ii-1)*4;  sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii]    ){q=ii*4;      sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii+1]  ){q=(ii+1)*4;  sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii+S-1]){q=(ii+S-1)*4;sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii+S]  ){q=(ii+S)*4;  sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        if(cov[ii+S+1]){q=(ii+S+1)*4;sr+=data[q];sg+=data[q+1];sb3+=data[q+2];}
        var a=cnt/9,ia=1-a,inv=1/cnt,oo=ii*4;
        data[oo]  =bd[oo]*ia+sr*inv*a;
        data[oo+1]=bd[oo+1]*ia+sg*inv*a;
        data[oo+2]=bd[oo+2]*ia+sb3*inv*a;
      }
    }
    ctx.putImageData(img,0,0);
  }
  return{render:render};
}

